const wildlifeDialog=document.getElementById('wildlifeDialog'),wildlifeProfile=document.getElementById('wildlifeProfile');
document.querySelector('.wildlife-close').addEventListener('click',()=>wildlifeDialog.close());
animalGrid.addEventListener('click',event=>{const button=event.target.closest('[data-profile]');if(button)openWildlifeProfile(button.dataset.profile)});
function profileSafe(value,fallback='Not recorded'){return String(value||fallback).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]))}
function countryName(code){try{return new Intl.DisplayNames([navigator.language||'en'],{type:'region'}).of(code)||code}catch{return code}}
async function profileJson(url){const response=await fetch(url);if(!response.ok)throw new Error(`${response.status}`);return response.json()}
async function openWildlifeProfile(scientific){
 const row=(window.pocketWildlife||[]).find(animal=>animal[1]===scientific),name=row?.[0]||scientific,page=row?.[4]||scientific,checked=new Date();
 wildlifeDialog.showModal();wildlifeProfile.innerHTML='<p class="database-status">Building sourced field entry…</p>';
 const [taxonResult,summaryResult]=await Promise.allSettled([profileJson(`https://api.gbif.org/v1/species/match?name=${encodeURIComponent(scientific)}`),profileJson(`https://en.wikipedia.org/api/rest_v1/page/summary/${encodeURIComponent(page)}`)]),taxon=taxonResult.status==='fulfilled'?taxonResult.value:null,summary=summaryResult.status==='fulfilled'?summaryResult.value:null,key=taxon?.usageKey||taxon?.speciesKey;
 let occurrence=null;if(key){try{occurrence=await profileJson(`https://api.gbif.org/v1/occurrence/search?taxon_key=${key}&limit=0&facet=country&facetLimit=12`)}catch{}}
 let mediaRecord=null;if(key){try{const mediaData=await profileJson(`https://api.gbif.org/v1/occurrence/search?taxon_key=${key}&media_type=StillImage&limit=20`);mediaRecord=mediaData.results?.find(item=>(item.media||[]).some(mediaItem=>mediaItem.identifier))||null}catch{}}
 const media=mediaRecord?.media?.find(item=>item.identifier),countries=(occurrence?.facets?.find(facet=>String(facet.field).toLowerCase()==='country')?.counts||[]).map(item=>({name:countryName(item.name),count:item.count})),classification=[['Kingdom',taxon?.kingdom],['Phylum',taxon?.phylum],['Class',taxon?.class],['Order',taxon?.order],['Family',taxon?.family],['Genus',taxon?.genus]].filter(item=>item[1]),photo=media?.identifier||summary?.originalimage?.source||summary?.thumbnail?.source,photoProvider=media?'GBIF occurrence media':'Wikimedia reference',photoCredit=media?.creator||media?.rightsHolder||mediaRecord?.institutionCode||'Contributor not supplied',photoLicense=media?.license||media?.rights||'Licence not supplied',photoSource=mediaRecord?.key?`https://www.gbif.org/occurrence/${mediaRecord.key}`:summary?.content_urls?.desktop?.page;
 wildlifeProfile.innerHTML=`<div class="wildlife-profile-hero">${photo?`<img src="${profileSafe(photo)}" alt="${profileSafe(name)} photograph">`:'<div class="profile-photo-missing">Photograph unavailable offline</div>'}<div><p class="eyebrow">FIELD ENTRY</p><h2>${profileSafe(name)}</h2><em>${profileSafe(scientific)}</em><span>${profileSafe(row?.[2])}</span></div></div><section class="profile-section"><div class="entry-kicker">IDENTIFICATION CONTEXT</div><h3>About this species</h3><p>${profileSafe(summary?.extract,'A verified descriptive account is not available from the connected reference source. Use the taxonomy and occurrence evidence below, and confirm identification with a qualified guide or regional field guide.')}</p><div class="profile-habitat"><small>Pocketbook habitat index</small><strong>${profileSafe(row?.[3])}</strong></div><p class="profile-caution">This description is reference material, not an image-identification result. Similar species, age, sex and local variation can cause mistakes.</p></section><section class="profile-section"><div class="entry-kicker">TAXONOMY</div><h3>Scientific classification</h3>${classification.length?`<div class="classification-grid">${classification.map(([rank,value])=>`<div><small>${rank}</small><strong>${profileSafe(value)}</strong></div>`).join('')}</div>`:'<div class="profile-unavailable">GBIF taxonomy could not be retrieved. The offline scientific name remains available.</div>'}</section><section class="profile-section"><div class="entry-kicker">OCCURRENCE EVIDENCE</div><h3>Countries represented in GBIF records</h3>${countries.length?`<div class="occurrence-list">${countries.map(country=>`<span><strong>${profileSafe(country.name)}</strong><small>${Number(country.count).toLocaleString()} records</small></span>`).join('')}</div><p class="profile-caution">These are database occurrence records, not a complete present-day range map. Record volume reflects reporting effort as well as occurrence.</p>`:'<div class="profile-unavailable">Recorded-country facets are unavailable while offline or were not returned for this taxon.</div>'}</section><section class="profile-section"><div class="entry-kicker">CONSERVATION</div><h3>Check current status</h3><p>The Pocketbook does not infer or cache a Red List category. Open the authoritative search to confirm the current assessment and publication date.</p><div class="profile-links">${key?`<a href="https://www.gbif.org/species/${key}" target="_blank" rel="noopener">GBIF taxon entry ↗</a>`:''}<a href="https://www.iucnredlist.org/search?query=${encodeURIComponent(scientific)}&searchType=species" target="_blank" rel="noopener">IUCN Red List search ↗</a></div></section><div class="profile-sources"><strong>Sources checked ${checked.toLocaleString()}</strong><span>GBIF Checklist Bank: taxonomy</span><span>GBIF Occurrence Store: recorded-country counts</span><span>Wikipedia/Wikimedia: descriptive reference and photograph</span><small>Counts and descriptions may change. Local guides and current conservation authorities remain essential.</small></div>`;
 if(photo){const hero=wildlifeProfile.querySelector('.wildlife-profile-hero');hero?.insertAdjacentHTML('afterend',`<div class="profile-media-credit"><strong>${profileSafe(photoProvider)}</strong><span>${profileSafe(photoCredit)} · ${profileSafe(photoLicense)}</span>${photoSource?`<a href="${profileSafe(photoSource)}" target="_blank" rel="noopener">Open media record ↗</a>`:''}</div>`)}
}
